const M = {};
M.config = (function () {
  const module = { exports: {} };
/**
 * config.js – builds the runtime config for every workflow from environment variables.
 * Used by the first "Config" Code node in each workflow. Secrets are NOT copied into
 * the output (execution data is stored in n8n); HTTP nodes read tokens from $env directly.
 */
function bool(v, dflt) {
  if (v === undefined || v === null || v === '') return dflt;
  return String(v).trim().toLowerCase() === 'true';
}

function parseList(v) {
  return String(v || '')
    .split(/[,;\s]+/)
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

function parseLimit(v, demoMode) {
  if (v === undefined || v === null || v === '') return demoMode ? 10 : null;
  if (String(v).trim().toLowerCase() === 'off') return null;
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : 10;
}

function trimSlash(u) {
  return String(u || '').replace(/\/+$/, '');
}

function buildConfig(env) {
  env = env || {};
  // Safe defaults: demo mode ON unless explicitly "false".
  const demoMode = bool(env.DEMO_MODE, true);
  const mock = bool(env.MOCK_EXTERNAL, false);
  const mockBase = trimSlash(env.MOCK_BASE_URL || 'http://host.docker.internal:8787');
  const real = {
    airtable: 'https://api.airtable.com/v0',
    googlePlaces: 'https://places.googleapis.com/v1',
    openai: 'https://api.openai.com/v1',
    anthropic: 'https://api.anthropic.com/v1',
    slack: 'https://slack.com/api',
    gmail: 'https://gmail.googleapis.com/gmail/v1',
    hubspot: 'https://api.hubapi.com',
    dns: 'https://dns.google',
    web: '',
    calendly: 'https://api.calendly.com',
  };
  const mocked = {
    airtable: mockBase + '/airtable/v0',
    googlePlaces: mockBase + '/google/v1',
    openai: mockBase + '/ai/openai/v1',
    anthropic: mockBase + '/ai/anthropic/v1',
    slack: mockBase + '/slack/api',
    gmail: mockBase + '/gmail/v1',
    hubspot: mockBase + '/hubspot',
    dns: mockBase + '/dns',
    web: mockBase + '/web',
    calendly: mockBase + '/calendly',
  };
  const urls = mock ? mocked : real;
  const aiProvider = String(env.AI_PROVIDER || 'openai').toLowerCase() === 'anthropic' ? 'anthropic' : 'openai';
  const allowlist = parseList(env.TEST_RECIPIENT_ALLOWLIST);
  const conf = parseFloat(env.AUTO_REPLY_MIN_CONFIDENCE);
  return {
    demoMode,
    mock,
    allowRealSending: !demoMode && bool(env.ALLOW_REAL_SENDING, false),
    // DEMO_MODE sends from an every-minute ticker; the test stack turns it off and drives sends by webhook
    demoTicker: !bool(env.DISABLE_DEMO_TICKER, false),
    // cap per run so one run always finishes before the next tick (no overlapping runs)
    // demo: 10 per minute tick with 1 s gaps (~45 s per run, so runs never overlap); real: 5 per 15-min tick, 60–180 s apart
    maxSendsPerRun: demoMode ? 10 : 5,
    testLeadLimit: parseLimit(env.TEST_LEAD_LIMIT, demoMode),
    allowlist,
    testProspectEmail: String(env.TEST_PROSPECT_EMAIL || '').trim().toLowerCase(),
    senderEmail: String(env.SENDER_EMAIL || '').trim().toLowerCase(),
    autoReplyMinConfidence: Number.isFinite(conf) ? conf : 0.85,
    unsureConfidence: 0.7,
    timezone: 'Europe/Berlin',
    airtableBaseId: env.AIRTABLE_BASE_ID || '',
    airtableUrl: urls.airtable + '/' + (env.AIRTABLE_BASE_ID || ''),
    googlePlacesUrl: urls.googlePlaces,
    aiProvider,
    aiModel: env.AI_MODEL || (aiProvider === 'anthropic' ? 'claude-haiku-5-5' : 'gpt-4o-mini'),
    aiUrl: aiProvider === 'anthropic' ? urls.anthropic + '/messages' : urls.openai + '/chat/completions',
    slackApiUrl: urls.slack,
    slackChannel: env.SLACK_CHANNEL || '#leads',
    gmailUrl: urls.gmail,
    hubspotUrl: urls.hubspot,
    dnsUrl: urls.dns,
    webProxyUrl: urls.web,
    calendlyLink: env.CALENDLY_LINK || '',
    calendlyApiUrl: urls.calendly,
    n8nBaseUrl: trimSlash(env.WEBHOOK_URL || 'http://localhost:5678'),
    n8nInternalUrl: trimSlash(env.N8N_INTERNAL_URL || 'http://localhost:5678'),
    interfaceUrl: env.AIRTABLE_INTERFACE_URL || (env.AIRTABLE_BASE_ID ? 'https://airtable.com/' + env.AIRTABLE_BASE_ID : ''),
    googleCostPerRequestEur: 0.032,
  };
}

/** URL to fetch a company web page; in mock mode served by the mock server. */
function webUrl(cfg, domain, path) {
  path = path || '/';
  if (cfg.webProxyUrl) return cfg.webProxyUrl + '/' + domain + path;
  return 'https://' + domain + path;
}

const configApi = { buildConfig, webUrl, parseList, parseLimit };
if (typeof module !== 'undefined' && module.exports) module.exports = configApi;

  return module.exports;
})();

// ---- node logic ----
const trigger = $input.all().map((i) => i.json);
// test stack only: schedules are switched off so tests drive every module through its webhook
const scheduled = trigger.length > 0 && trigger[0] && trigger[0]['Readable date'] !== undefined;
if (scheduled && String($env.DISABLE_SCHEDULES).toLowerCase() === 'true') return [];
return [{ json: { cfg: M.config.buildConfig($env), trigger, startedAt: new Date().toISOString() } }];

const M = {};
M.reminders = (function () {
  const module = { exports: {} };
/**
 * reminders.js – Module 7c (hourly): 24 h reminder emails and "held or no-show?" checks.
 */
function dueReminders(meetings, now) {
  const t = new Date(now || Date.now()).getTime();
  const reminders = [];
  const heldChecks = [];
  (meetings || []).forEach((m) => {
    if (!m.start_time) return;
    const start = new Date(m.start_time).getTime();
    if (m.status === 'Booked' && !m.reminder_sent_at && start - t <= 24 * 3600000 && start > t) reminders.push(m);
    if ((m.status === 'Booked' || m.status === 'Reminded') && !m.held_check_sent_at && t >= start + 15 * 60000) heldChecks.push(m);
  });
  return { reminders, heldChecks };
}

function reminderEmail(meeting, lead, client, berlinTime, ve) {
  const text = `ich freue mich auf unser Gespräch am ${berlinTime}. Falls etwas dazwischenkommt, können Sie den Termin über den Link in der Calendly-Bestätigung verschieben.`;
  const body = ve
    ? ve.ensureFrame(text, { contactName: lead.contact_name, contactSalutation: lead.contact_salutation, signature: ve.buildSignature(client || {}) })
    : `Guten Tag ${lead.contact_name || ''},\n\n${text}\n\nMit freundlichen Grüßen\n\n${(client && client.sender_name) || 'Ihr Nexsale-Team'}`.replace(/Tag \s*,/, 'Tag,');
  return { to: lead.email, subject: 'Erinnerung: unser Termin morgen', body, purpose: 'reminder' };
}

function formatBerlin(iso) {
  return new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'full', timeStyle: 'short' }).format(new Date(iso)) + ' Uhr';
}

const remindersApi = { dueReminders, reminderEmail, formatBerlin };
if (typeof module !== 'undefined' && module.exports) module.exports = remindersApi;

  return module.exports;
})();

M.airtable = (function () {
  const module = { exports: {} };
/**
 * airtable.js – helpers for the Airtable REST API: batches of 10, formula building,
 * flattening records. Free-plan friendly (CLAUDE.md: batches of 10 per call).
 */
const BATCH = 10;

function chunk(list, size) {
  const n = size || BATCH;
  const out = [];
  for (let i = 0; i < (list || []).length; i += n) out.push(list.slice(i, i + n));
  return out;
}

function clean(fields) {
  const out = {};
  Object.keys(fields || {}).forEach((k) => {
    if (fields[k] !== undefined) out[k] = fields[k];
  });
  return out;
}

/** -> [{records:[{fields}]}] one item per HTTP call */
function createBatches(fieldsList) {
  return chunk((fieldsList || []).map((f) => ({ fields: clean(f) }))).map((records) => ({ records, typecast: true }));
}

/** updates: [{id, fields}] -> [{records:[{id, fields}]}] */
function updateBatches(updates) {
  return chunk((updates || []).filter((u) => u && u.id).map((u) => ({ id: u.id, fields: clean(u.fields) }))).map((records) => ({ records, typecast: true }));
}

function esc(v) {
  return String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function eq(field, value) {
  if (typeof value === 'number' || typeof value === 'boolean') return `{${field}}=${value === true ? 'TRUE()' : value === false ? 'FALSE()' : value}`;
  return `{${field}}='${esc(value)}'`;
}

function and(...parts) {
  const p = parts.filter(Boolean);
  return p.length === 1 ? p[0] : `AND(${p.join(',')})`;
}

function or(...parts) {
  const p = parts.filter(Boolean);
  return p.length === 1 ? p[0] : `OR(${p.join(',')})`;
}

/** Airtable record -> flat object with id */
function flat(record) {
  if (!record) return null;
  return Object.assign({ id: record.id, createdTime: record.createdTime }, record.fields || {});
}

function flatList(response) {
  return ((response && response.records) || []).map(flat);
}

/** n8n items from a (paginated) list node -> flat records */
function fromItems(items) {
  // With pagination on, n8n's HTTP node retries and then passes the error body on instead of failing.
  // A failed read must never look like an empty table (e.g. an "empty" Blocklist), so fail here.
  (items || []).forEach((i) => {
    const e = i && i.json && i.json.error;
    if (e) throw new Error('Airtable read failed after retries: ' + (typeof e === 'string' ? e : e.message || e.type || JSON.stringify(e)).slice(0, 200));
  });
  return flatList({ records: (items || []).flatMap((i) => (i && i.json && i.json.records) || []) });
}

/** OR() over ids for a text field, e.g. lead_record_id */
function inIds(field, ids) {
  const list = Array.from(new Set((ids || []).filter(Boolean)));
  if (!list.length) return "{" + field + "}='__none__'";
  return or(...list.map((id) => eq(field, id)));
}

const airtableApi = { fromItems, inIds, BATCH, chunk, createBatches, updateBatches, eq, and, or, esc, flat, flatList, clean };
if (typeof module !== 'undefined' && module.exports) module.exports = airtableApi;

  return module.exports;
})();

// ---- node logic ----
const m = M.airtable.fromItems($('Open meetings').all());
const r = M.reminders.dueReminders(m, new Date());
if (!r.reminders.length && !r.heldChecks.length) return [];
const ids = Array.from(new Set(r.reminders.concat(r.heldChecks).map((x) => x.lead_record_id)));
return [{ json: { reminders: r.reminders, heldChecks: r.heldChecks, formula: 'OR(' + ids.map((id) => "RECORD_ID()='" + id + "'").join(',') + ')' } }];

